/*!40000 ALTER TABLE `item` DISABLE KEYS */;
INSERT INTO `item` VALUES (1,'Acid',1,2500,2,0,0,'Common','When you take the Attack action, you can replace one of your attacks with throwing a vial of Acid. Target one creature or object you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 2d6 Acid damage.'),(2,'Airship',0,4000000,14,0,0,'Common','A magical flying vessel capable of air travel.'),(3,'Alchemist\'s Fire',1,5000,2,0,0,'Common','When you take the Attack action, you can replace one of your attacks with throwing a flask of Alchemist\'s Fire. Target one creature or object you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 1d4 Fire damage and start burning (see \"Rules Glossary\").'),(4,'Alchemist\'s Supplies (50 GP)',8,5000,5,0,0,'Common','Ability: Intelligence. Utilize: Identify a substance (DC 15), or start a fire (DC 15). Craft: Acid, Alchemist\'s Fire, Component Pouch, Oil, Paper, Perfume'),(5,'Antitoxin',0,5000,7,0,0,'Common','As a Bonus Action, you can drink a vial of Antitoxin to gain Advantage on saving throws to avoid or end the Poisoned condition for 1 hour. abo'),(6,'Arrows (20)',1,100,13,0,0,'Common','Ammunition for weapons that use arrows. Comes in a pack of 20. Typically stored in a quiver.'),(7,'Backpack',5,200,16,0,0,'Common','A Backpack holds up to 30 pounds within 1 cubic foot. It can also serve as a saddlebag.'),(8,'Ball Bearings',2,100,16,0,0,'Common','As a Utilize action, you can spill Ball Bearings from their pouch. They spread to cover a level, 10-footsquare area within 10 feet of yourself. A creature that enters this area for the first time on a turn must succeed on a DC 10 Dexterity saving throw or have the Prone condition. It takes 10 minutes to recover the Ball Bearings.'),(9,'Barrel',70,200,16,0,0,'Common','A Barrel holds up to 40 gallons of liquid or up to 4 cubic feet of dry goods.'),(10,'Basket',2,40,16,0,0,'Common','A Basket holds up to 40 pounds within 2 cubic feet.'),(11,'Battleaxe',4,1000,2,0,0,'Common','A battleaxe.'),(12,'Bedroll',7,100,16,0,0,'Common','A Bedroll sleeps one Small or Medium creature. While in a Bedroll, you automatically succeed on saving throws against extreme cold (see \"Gameplay Toolbox\").'),(13,'Bell',0,100,16,0,0,'Common','When rung as a Utilize action, a Bell produces a sound that can be heard up to 60 feet away.'),(14,'Blanket',3,50,16,0,0,'Common','While wrapped in a blanket, you have Advantage on saving throws against extreme cold (see \"Gameplay Toolbox\").'),(15,'Block and Tackle',5,100,16,0,0,'Common','A Block and Tackle allows you to hoist up to four times the weight you can normally lift.'),(16,'Blowgun',1,1000,2,0,0,'Common','A blowgun.'),(17,'Bolts (20)',1.5,100,13,0,0,'Common','Ammunition for weapons that use bolts. Comes in a pack of 20. Typically stored in a case.'),(18,'Book',5,2500,16,0,0,'Common','A Book contains fiction or nonfiction. If you consult an accurate nonfiction Book about its topic, you gain a +5 bonus to Intelligence (Arcana, History, Nature, or Religion) checks you make about that topic.'),(19,'Bottle, Glass',2,200,16,0,0,'Common','A Glass Bottle holds up to 1 0.5 pints.'),(20,'Breastplate',20,40000,1,0,0,'Common','A breastplate.'),(21,'Brewer\'s Supplies (20 GP)',9,2000,5,0,0,'Common','Ability: Intelligence. Utilize: Detect poisoned drink (DC 15), or identify alcohol (DC 10). Craft: Antitoxin'),(22,'Bucket',2,5,16,0,0,'Common','A Bucket holds up to half a cubic foot of contents.'),(23,'Bullets, Firearm (10)',2,300,13,0,0,'Common','Ammunition for weapons that use bullets, firearm. Comes in a pack of 10. Typically stored in a pouch.'),(24,'Bullets, Sling (20)',1.5,4,13,0,0,'Common','Ammunition for weapons that use bullets, sling. Comes in a pack of 20. Typically stored in a pouch.'),(25,'Burglar\'s Pack',42,1600,16,0,0,'Common','A Burglar\'s Pack contains the following items: Backpack, Ball Bearings, Bell, 10 Candles, Crowbar, Hooded Lantern, 7 flasks of Oil, 5 days of Rations, Rope, Tinderbox, and Waterskin.'),(26,'Calligrapher\'s Supplies (10 GP)',5,1000,5,0,0,'Common','Ability: Dexterity. Utilize: Write text with impressive flourishes that guard against forgery (DC 15). Craft: Ink, *Spell Scroll*'),(27,'Caltrops',2,100,16,0,0,'Common','As a Utilize action, you can spread Caltrops from their bag to cover a 5-foot-square area within 5 feet of yourself. A creature that enters this area for the first time on a turn must succeed on a DC 15 Dexterity saving throw or take 1 Piercing damage and have its Speed reduced to 0 until the start of its next turn. It takes 10 minutes to recover the Caltrops.'),(28,'Camel',0,5000,15,0,0,'Common','A desert-dwelling mount capable of carrying heavy loads.'),(29,'Candle',0,1,16,0,0,'Common','For 1 hour, a lit Candle sheds Bright Light in a 5-foot radius and Dim Light for an additional 5 feet.'),(30,'Carpenter\'s Tools (8 GP)',6,800,5,0,0,'Common','Ability: Strength. Utilize: Seal or pry open a door or container (DC 20). Craft: Club, Greatclub, Quarterstaff, Barrel, Chest, Ladder, Pole, Portable Ram, Torch'),(31,'Carriage',600,10000,15,0,0,'Common','A four-wheeled vehicle pulled by horses, designed for passenger transport.'),(32,'Cart',200,1500,15,0,0,'Common','A two-wheeled vehicle pulled by a single horse, designed for cargo transport.'),(33,'Cartographer\'s Tools (15 GP)',6,1500,5,0,0,'Common','Ability: Wisdom. Utilize: Draft a map of a small area (DC 15). Craft: Map'),(34,'Case, Crossbow Bolt',1,100,16,0,0,'Common','A Crossbow Bolt Case holds up to 20 Bolts.'),(35,'Case, Map or Scroll',1,100,16,0,0,'Common','A Map or Scroll Case holds up to 10 sheets of paper or 5 sheets of parchment.'),(36,'Chain',10,500,16,0,0,'Common','As a Utilize action, you can wrap a Chain around an unwilling creature within 5 feet of yourself that has the Grappled, Incapacitated, or Restrained condition if you succeed on a DC 13 Strength (Athletics) check. If the creature\'s legs are bound, the creature has the Restrained condition until it escapes. Escaping the Chain requires the creature to make a successful DC 18 Dexterity (Acrobatics) check as an action. Bursting the Chain requires a successful DC 20 Strength (Athletics) check as an action.'),(37,'Chain Mail',55,7500,1,0,0,'Common','A chain mail.'),(38,'Chain Shirt',20,5000,1,0,0,'Common','A chain shirt.'),(39,'Chariot',100,25000,15,0,0,'Common','A two-wheeled vehicle pulled by horses, designed for speed and combat.'),(40,'Chest',25,500,16,0,0,'Common','A Chest holds up to 12 cubic feet of contents.'),(41,'Climber\'s Kit',12,2500,5,0,0,'Common','A Climber\'s Kit includes boot tips, gloves, pitons, and a harness. As a Utilize action, you can use the Climber\'s Kit to anchor yourself; when you do, you can\'t fall more than 25 feet from the anchor point, and you can\'t move more than 25 feet from there without undoing the anchor as a Bonus Action.'),(42,'Clothes, Fine',6,1500,16,0,0,'Common','Fine Clothes are made of expensive fabrics and adorned with expertly crafted details. Some events and locations admit only people wearing these clothes.'),(43,'Clothes, Traveler\'s',4,200,16,0,0,'Common','Traveler\'s Clothes are resilient garments designed for travel in various environments.'),(44,'Club',2,10,2,0,0,'Common','A club.'),(45,'Cobbler\'s Tools (5 GP)',5,500,5,0,0,'Common','Ability: Dexterity. Utilize: Modify footwear to give Advantage on the wearer\'s next Dexterity (Acrobatics) check (DC 10). Craft: Climber\'s Kit'),(46,'Component Pouch',2,2500,16,0,0,'Common','A Component Pouch is watertight and filled with compartments that hold all the free Material components of your spells.'),(47,'Cook\'s Utensils (1 GP)',8,100,5,0,0,'Common','Ability: Wisdom. Utilize: Improve food\'s flavor (DC 10), or detect spoiled or poisoned food (DC 15). Craft: Rations'),(48,'Costume',4,500,16,0,0,'Common','While wearing a Costume, you have Advantage on any ability check you make to impersonate the person or type of person it represents.'),(49,'Crowbar',5,200,16,0,0,'Common','Using a Crowbar gives you Advantage on Strength checks where the Crowbar\'s leverage can be applied.'),(50,'Dagger',1,200,2,0,0,'Common','A dagger.'),(51,'Dart',1,5,2,0,0,'Common','A dart.'),(52,'Diplomat\'s Pack',39,3900,16,0,0,'Common','A Diplomat\'s Pack contains the following items: Chest, Fine Clothes, Ink, 5 Ink Pens, Lamp, 2 Map or Scroll Cases, 4 flasks of Oil, 5 sheets of Paper, 5 sheets of Parchment, Perfume, and Tinderbox.'),(53,'Disguise Kit',3,2500,5,0,0,'Common','Ability: Charisma. Utilize: Apply makeup (DC 10). Craft: Costume'),(54,'Druidic Focus, Sprig of Mistletoe',0,100,14,0,0,'Common','A Druidic Focus is carved, tied with ribbon, or painted to channel primal magic. A Druid or Ranger can use such an object as a Spellcasting Focus.'),(55,'Druidic Focus, Wooden Staff',4,500,14,0,0,'Common','A Druidic Focus is carved, tied with ribbon, or painted to channel primal magic. A Druid or Ranger can use such an object as a Spellcasting Focus. This staff can also be used as a Quarterstaff.'),(56,'Druidic Focus, Yew Wand',1,1000,14,0,0,'Common','A Druidic Focus is carved, tied with ribbon, or painted to channel primal magic. A Druid or Ranger can use such an object as a Spellcasting Focus.'),(57,'Dungeoneer\'s Pack',55,1200,16,0,0,'Common','A Dungeoneer\'s Pack contains the following items: Backpack, Caltrops, Crowbar, 2 flasks of Oil, 10 days of Rations, Rope, Tinderbox, 10 Torches, and Waterskin.'),(58,'Elephant',0,20000,15,0,0,'Common','A massive mount capable of carrying extremely heavy loads.'),(59,'Entertainer\'s Pack',58,4000,16,0,0,'Common','An Entertainer\'s Pack contains the following items: Backpack, Bedroll, Bell, Bullseye Lantern, 3 Costumes, Mirror, 8 flasks of Oil, 9 days of Rations, Tinderbox, and Waterskin.'),(60,'Explorer\'s Pack',55,1000,16,0,0,'Common','An Explorer\'s Pack contains the following items: Backpack, Bedroll, 2 flasks of Oil, 10 days of Rations, Rope, Tinderbox, 10 Torches, and Waterskin.'),(61,'Feed (per day)',10,5,16,0,0,'Common','Daily feed for a mount.'),(62,'Flail',2,1000,2,0,0,'Common','A flail.'),(63,'Flask',1,2,16,0,0,'Common','A Flask holds up to 1 pint.'),(64,'Forgery Kit',5,1500,5,0,0,'Common','Ability: Dexterity. Utilize: Mimic 10 or fewer words of someone else\'s handwriting (DC 15), or duplicate a wax seal (DC 20)'),(65,'Galley',0,3000000,15,0,0,'Common','A large warship propelled by oars and sails.'),(66,'Gaming Set, Dice',0,10,5,0,0,'Common','Ability: Wisdom. Utilize: Discern whether someone is cheating (DC 10), or win the game (DC 20)'),(67,'Gaming Set, Dragonchess',1,100,5,0,0,'Common','Ability: Intelligence. Utilize: Discern an opponent\'s mood and intentions (DC 15), or win the game (DC 20)'),(68,'Gaming Set, Playing Cards',0,50,5,0,0,'Common','Ability: Charisma. Utilize: Discern an opponent\'s mood and intentions (DC 15), or win the game (DC 20)'),(69,'Gaming Set, Three-Dragon Ante',0,100,5,0,0,'Common','Ability: Charisma. Utilize: Discern an opponent\'s mood and intentions (DC 15), or win the game (DC 20)'),(70,'Glaive',6,2000,2,0,0,'Common','A glaive.'),(71,'Glassblower\'s Tools (30 GP)',5,3000,5,0,0,'Common','Ability: Intelligence. Utilize: Discern what a glass object held in the past 24 hours (DC 15). Craft: Glass Bottle, Magnifying Glass, Spyglass, Vial'),(72,'Grappling Hook',4,200,16,0,0,'Common','As a Utilize action, you can throw the Grappling Hook at a railing, a ledge, or another catch within 50 feet of yourself, and the hook catches on if you succeed on a DC 13 Dexterity (Acrobatics) check. If you tied a Rope to the hook, you can then climb it.'),(73,'Greataxe',7,3000,2,0,0,'Common','A greataxe.'),(74,'Greatclub',10,20,2,0,0,'Common','A greatclub.'),(75,'Greatsword',6,5000,2,0,0,'Common','A greatsword.'),(76,'Halberd',6,2000,2,0,0,'Common','A halberd.'),(77,'Half Plate Armor',40,75000,1,0,0,'Common','A half plate armor.'),(78,'Hand Crossbow',3,7500,2,0,0,'Common','A hand crossbow.'),(79,'Handaxe',2,500,2,0,0,'Common','A handaxe.'),(80,'Healer\'s Kit',3,500,5,0,0,'Common','A Healer\'s Kit has ten uses. As a Utilize action, you can expend one of its uses to stabilize an Unconscious creature that has 0 Hit Points without needing to make a Wisdom (Medicine) check.'),(81,'Heavy Crossbow',18,5000,2,0,0,'Common','A heavy crossbow.'),(82,'Herbalism Kit',3,500,5,0,0,'Common','Ability: Intelligence. Utilize: Identify a plant (DC 15). Craft: Antitoxin, Potion of Healing'),(83,'Hide Armor',12,1000,1,0,0,'Common','A hide armor.'),(84,'Holy Symbol, Amulet)',1,500,16,0,0,'Common','A Holy Symbol Amulet is bejeweled or painted to channel divine magic. A Cleric or Paladin can use it as a Spellcasting Focus. It can be worn around the neck or held in hand.'),(85,'Holy Symbol, Emblem)',0,500,16,0,0,'Common','A Holy Symbol Emblem is bejeweled or painted to channel divine magic. A Cleric or Paladin can use it as a Spellcasting Focus. It must be borne on fabric (such as a tabard or banner) or a Shield.'),(86,'Holy Symbol, Reliquary',2,500,16,0,0,'Common','A Holy Symbol Reliquary is bejeweled or painted to channel divine magic. A Cleric or Paladin can use it as a Spellcasting Focus. It must be held in hand.'),(87,'Holy Water',1,2500,2,0,0,'Common','When you take the Attack action, you can replace one of your attacks with throwing a flask of Holy Water. Target one creature you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 2d8 Radiant damage if it is a Fiend or an Undead.'),(88,'Horse (Draft)',0,5000,15,0,0,'Common','A strong horse bred for pulling heavy loads.'),(89,'Horse (Riding)',0,7500,15,0,0,'Common','A horse trained for riding and carrying moderate loads.'),(90,'Hunting Trap',25,500,16,0,0,'Common','As a Utilize action, you can set a Hunting Trap, which is a sawtooth steel ring that snaps shut when a creature steps on a pressure plate in the center. The trap is affixed by a heavy chain to an immobile object, such as a tree or a spike driven into the ground. A creature that steps on the plate must succeed on a DC 13 Dexterity saving throw or take 1d4 Piercing damage and have its Speed reduced to 0 until the start of its next turn. Thereafter, until the creature breaks free of the trap, its movement is limited by the length of the chain (typically 3 feet). A creature can use its action to make a DC 13 Strength (Athletics) check, freeing itself or another creature within its reach on a success. Each failed check deals 1 Piercing damage to the trapped creature.'),(91,'Ink',0,1000,16,0,0,'Common','Ink comes in a 1-ounce bottle, which provides enough ink to write about 500 pages.'),(92,'Ink Pen',0,2,16,0,0,'Common','Using Ink, an Ink Pen is used to write or draw.'),(93,'Ioun Stone',0,0,14,0,0,'Common','Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color. When you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three Ioun Stones orbiting your head at the same time. Each Ioun Stone orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it. As a Utilize action, you can seize and stow any number of Ioun Stones orbiting your head. If your Attunement to an Ioun Stone ends while it\'s orbiting your head, the stone falls as though you had dropped it. The type of stone determines its rarity and effects. Absorption (Very Rare). While this pale lavender ellipsoid orbits your head, you can take a Reaction to cancel a spell of level 4 or lower cast by a creature you can see. A canceled spell has no effect, and any resources used to cast it are wasted. Once the stone has canceled 20 levels of spells, it burns out, turns dull gray, and loses its magic. Agility (Very Rare). Your Dexterity increases by 2, to a maximum of 20, while this deep-red sphere orbits your head. Awareness (Rare). While this dark-blue rhomboid orbits your head, you have Advantage on Initiative rolls and Wisdom (Perception) checks. Fortitude (Very Rare). Your Constitution increases by 2, to a maximum of 20, while this pink rhomboid orbits your head. Greater Absorption (Legendary). While this marbled lavender and green ellipsoid orbits your head, you can take a Reaction to cancel a spell of level 8 or lower cast by a creature you can see. A canceled spell has no effect, and any resources used to cast it are wasted. Once the stone has canceled 20 levels of spells, it burns out, turns dull gray, and loses its magic. Insight (Very Rare). Your Wisdom increases by 2, to a maximum of 20, while this incandescent blue sphere orbits your head. Intellect (Very Rare). Your Intelligence increases by 2, to a maximum of 20, while this marbled scarlet and blue sphere orbits your head. Leadership (Very Rare). Your Charisma increases by 2, to a maximum of 20, while this marbled pink and green sphere orbits your head. Mastery (Legendary). Your Proficiency Bonus increases by 1 while this pale green prism orbits your head. Protection (Rare). You gain a +1 bonus to Armor Class while this dusty-rose prism orbits your head. Regeneration (Legendary). You regain 15 Hit Points at the end of each hour this pearly white spindle orbits your head if you have at least 1 Hit Point. Reserve (Rare). This vibrant purple prism stores spells cast into it, holding them until you use them. The stone can store up to 4 levels of spells at a time. When found, it contains 1d4 levels of stored spells chosen by the GM. Any creature can cast a spell of level 1 through 4 into the stone by touching it as the spell is cast. The spell has no effect, other than to be stored in the stone. If the stone can\'t hold the spell, the spell is expended without effect. The level of the slot used to cast the spell determines how much space it uses. While this stone orbits your head, you can cast any spell stored in it. The spell uses the slot level, spell save DC, spell attack bonus, and spellcasting ability of the original caster but is otherwise treated as if you cast the spell. The spell cast from the stone is no longer stored in it, freeing up space. Strength (Very Rare). Your Strength increases by 2, to a maximum of 20, while this pale blue rhomboid orbits your head. Sustenance (Rare). You don\'t need to eat or drink while this clear spindle orbits your head.'),(94,'Javelin',2,50,2,0,0,'Common','A javelin.'),(95,'Jeweler\'s Tools (25 GP)',2,2500,5,0,0,'Common','Ability: Intelligence. Utilize: Discern a gem\'s value (DC 15). Craft: Arcane Focus, Holy Symbol'),(96,'Jug',4,2,16,0,0,'Common','A Jug holds up to 1 gallon.'),(97,'Keelboat',0,300000,15,0,0,'Common','A small riverboat with a keel.'),(98,'Ladder',25,10,16,0,0,'Common','A Ladder is 10 feet tall. You must climb to move up or down it.'),(99,'Lamp',1,50,16,0,0,'Common','A Lamp burns Oil as fuel to cast Bright Light in a 15 foot radius and Dim Light for an additional 30 feet.'),(100,'Lance',6,1000,2,0,0,'Common','A lance.'),(101,'Lantern, Bullseye',2,1000,16,0,0,'Common','A Bullseye Lantern burns Oil as fuel to cast Bright Light in a 60-foot Cone and Dim Light for an additional 60 feet.'),(102,'Lantern, Hooded',2,500,16,0,0,'Common','A Hooded Lantern burns Oil as fuel to cast Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. As a Bonus Action, you can lower the hood, reducing the light to Dim Light in a 5-foot radius, or raise it again.'),(103,'Leather Armor',10,1000,1,0,0,'Common','A leather armor.'),(104,'Leatherworker\'s Tools (5 GP)',5,500,5,0,0,'Common','Ability: Dexterity. Utilize: Add a design to a leather item (DC 10). Craft: Sling, Whip, Hide Armor, Leather Armor, Studded Leather Armor, Backpack, Crossbow Bolt Case, Map or Scroll Case, Parchment, Pouch, Quiver, Waterskin'),(105,'Light Crossbow',5,2500,2,0,0,'Common','A light crossbow.'),(106,'Light Hammer',2,200,2,0,0,'Common','A light hammer.'),(107,'Lock',1,1000,16,0,0,'Common','A Lock comes with a key. Without the key, a creature can use Thieves\' Tools to pick this Lock with a successful DC 15 Dexterity (Sleight of Hand) check.'),(108,'Longbow',2,5000,2,0,0,'Common','A longbow.'),(109,'Longship',0,1000000,15,0,0,'Common','A swift ship designed for raiding and exploration.'),(110,'Longsword',3,1500,2,0,0,'Common','A longsword.'),(111,'Mace',4,500,2,0,0,'Common','A mace.'),(112,'Magnifying Glass',0,10000,16,0,0,'Common','A Magnifying Glass grants Advantage on any ability check made to appraise or inspect a highly detailed item. Lighting a fire with a Magnifying Glass requires light as bright as sunlight to focus, tinder to ignite, and about 5 minutes for the fire to ignite.'),(113,'Manacles',6,200,16,0,0,'Common','As a Utilize action, you can use Manacles to bind an unwilling Small or Medium creature within 5 feet of yourself that has the Grappled, Incapacitated, or Restrained condition if you succeed on a DC 13 Dexterity (Sleight of Hand) check. While bound, a creature has Disadvantage on attack rolls, and the creature is Restrained if the Manacles are attached to a chain or hook that is fixed in place. Escaping the Manacles requires a successful DC 20 Dexterity (Sleight of Hand) check as an action. Bursting them requires a successful DC 25 Strength (Athletics) check as an action. Each set of Manacles comes with a key. Without the key, a creature can use Thieves\' Tools to pick the Manacles\' lock with a successful DC 15 Dexterity (Sleight of Hand) check.'),(114,'Map',0,100,16,0,0,'Common','If you consult an accurate Map, you gain a +5 bonus to Wisdom (Survival) checks you make to find your way in the place represented on it.'),(115,'Mason\'s Tools (10 GP)',8,1000,5,0,0,'Common','Ability: Strength. Utilize: Chisel a symbol or hole in stone (DC 10). Craft: Block and Tackle'),(116,'Mastiff',0,2500,15,0,0,'Common','A large dog trained for combat and carrying small loads.'),(117,'Maul',10,1000,2,0,0,'Common','A maul.'),(118,'Mirror',0.5,500,16,0,0,'Common','A handheld steel Mirror is useful for personal cosmetics but also for peeking around corners and reflecting light as a signal.'),(119,'Morningstar',4,1500,2,0,0,'Common','A morningstar.'),(120,'Mule',0,800,15,0,0,'Common','A sturdy mount known for its reliability and carrying capacity.'),(121,'Musical Instrument, Bagpipes',6,3000,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(122,'Musical Instrument, Drum',3,600,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(123,'Musical Instrument, Dulcimer',10,2500,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(124,'Musical Instrument, Flute',1,200,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(125,'Musical Instrument, Horn',2,300,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(126,'Musical Instrument, Lute',2,3500,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(127,'Musical Instrument, Lyre',2,3000,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(128,'Musical Instrument, Pan Flute',2,1200,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(129,'Musical Instrument, Shawm',1,200,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(130,'Musical Instrument, Viol',1,3000,5,0,0,'Common','Ability: Charisma. Utilize: Identify a musical piece (DC 15)'),(131,'Musket',10,50000,2,0,0,'Common','A musket.'),(132,'Navigator\'s Tools',2,2500,5,0,0,'Common','Ability: Wisdom. Utilize: Plot a course (DC 15), or determine position (DC 15)'),(133,'Needles (50)',1,100,13,0,0,'Common','Ammunition for weapons that use needles. Comes in a pack of 50. Typically stored in a pouch.'),(134,'Net',3,100,2,0,0,'Common','When you take the Attack action, you can replace one of your attacks with throwing a Net. Target a creature you can see within 15 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or have the Restrained condition until it escapes. The target succeeds automatically if it is Huge or larger. To escape, the target or a creature within 5 feet of it must take an action to make a DC 10 Strength (Athletics) check, freeing the Restrained creature on a success. Destroying the Net (AC 10; 5 HP; Immunity to Bludgeoning, Poison, and Psychic damage) also frees the target, ending the effect.'),(135,'Oil',1,10,2,0,0,'Common','You can douse a creature, object, or space with Oil or use it as fuel, as detailed below. Dousing a Creature or an Object. When you take the Attack action, you can replace one of your attacks with throwing an Oil flask. Target one creature or object within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or be covered in oil. If the target takes Fire damage before the oil dries (after 1 minute), the target takes an extra 5 Fire damage from burning oil. Dousing a Space. You can take the Utilize action to pour an Oil flask on level ground to cover a 5-foot-square area within 5 feet of yourself. If lit, the oil burns until the end of the turn 2 rounds from when the oil was lit (or 12 seconds) and deals 5 Fire damage to any creature that enters the area or ends its turn there. A creature can take this damage only once per turn. Fuel. Oil serves as fuel for Lamps and Lanterns. Once lit, a flask of Oil burns for 6 hours in a Lamp or Lantern. That duration doesn\'t need to be consecutive; you can extinguish the burning Oil (as a Utilize action) and rekindle it again until it has burned for a total of 6 hours.'),(136,'Padded Armor',8,500,1,0,0,'Common','A padded armor.'),(137,'Painter\'s Supplies (10 GP)',5,1000,5,0,0,'Common','Ability: Wisdom. Utilize: Paint a recognizable image of something you\'ve seen (DC 10). Craft: Druidic Focus, Holy Symbol'),(138,'Paper',0,20,16,0,0,'Common','One sheet of Paper can hold about 250 handwritten words.'),(139,'Parchment',0,10,16,0,0,'Common','One sheet of Parchment can hold about 250 handwritten words.'),(140,'Perfume',0,500,16,0,0,'Common','Perfume comes in a 4-ounce vial. For 1 hour after applying Perfume to yourself, you have Advantage on Charisma (Persuasion) checks made to influence an Indifferent Humanoid within 5 feet of yourself.'),(141,'Pike',18,500,2,0,0,'Common','A pike.'),(142,'Pistol',3,25000,2,0,0,'Common','A pistol.'),(143,'Plate Armor',65,150000,1,0,0,'Common','A plate armor.'),(144,'Poison, Basic',0,10000,16,0,0,'Common','As a Bonus Action, you can use a vial of Basic Poison to coat one weapon or up to three pieces of ammunition. A creature that takes Piercing or Slashing damage from the poisoned weapon or ammunition takes an extra 1d4 Poison damage. Once applied, the poison retains potency for 1 minute or until its damage is dealt, whichever comes first.'),(145,'Poisoner\'s Kit',2,5000,5,0,0,'Common','Ability: Intelligence. Utilize: Detect a poisoned object (DC 10). Craft: Basic Poison'),(146,'Pole',7,5,16,0,0,'Common','A Pole is 10 feet long. You can use it to touch something up to 10 feet away. If you must make a Strength (Athletics) check as part of a High or Long Jump, you can use the Pole to vault, giving yourself Advantage on the check.'),(147,'Pony',0,3000,15,0,0,'Common','A small horse suitable for smaller riders and lighter loads.'),(148,'Pot, Iron',10,200,16,0,0,'Common','An Iron Pot holds up to 1 gallon.'),(149,'Potion of Giant Strength',0,0,7,0,0,'Common','When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score (see the table below). The potion has no effect on you if your Strength is equal to or greater than that score.\n\nThis potion\'s transparent liquid has floating in it a sliver of light resembling a giant\'s fingernail.\n\n| Potion                                    | Str. | Rarity    |\n|-------------------------------------------|------|-----------|\n| Potion of Giant Strength (hill)           | 21   | Uncommon  |\n| Potion of Giant Strength (frost or stone) | 23   | Rare      |\n| Potion of Giant Strength (fire)           | 25   | Rare      |\n| Potion of Giant Strength (cloud)          | 27   | Very Rare |\n| Potion of Giant Strength (storm)          | 29   | Legendary |'),(150,'Potion of Healing',0.5,5000,7,0,0,'Common','This potion is a magic item. As a Bonus Action, you can drink it or administer it to another creature within 5 feet of yourself. The creature that drinks the magical red fluid in this vial regains 2d4 + 2 Hit Points.'),(151,'Potions of Healing',0,0,7,0,0,'Common','You regain Hit Points when you drink this potion. The number of Hit Points depends on the potion\'s rarity, as shown in the table below.\n\nWhatever its potency, the potion\'s red liquid glimmers when agitated.\n\n| Potion                       | HP Regained | Rarity    |\n|------------------------------|-------------|-----------|\n| Potion of Healing            | 2d4 + 2     | Common    |\n| Potion of Healing (greater)  | 4d4 + 4     | Uncommon  |\n| Potion of Healing (superior) | 8d4 + 8     | Rare      |\n| Potion of Healing (supreme)  | 10d4 + 20   | Very Rare |'),(152,'Potter\'s Tools (10 GP)',3,1000,5,0,0,'Common','Ability: Intelligence. Utilize: Discern what a ceramic object held in the past 24 hours (DC 15). Craft: Jug, Lamp'),(153,'Pouch',1,50,16,0,0,'Common','A Pouch holds up to 6 pounds within one-fifth of a cubic foot.'),(154,'Priest\'s Pack',29,3300,16,0,0,'Common','A Priest\'s Pack contains the following items: Backpack, Blanket, Holy Water, Lamp, 7 days of Rations, Robe, and Tinderbox.'),(155,'Quarterstaff',4,20,2,0,0,'Common','A quarterstaff.'),(156,'Quiver',1,100,16,0,0,'Common','A Quiver holds up to 20 Arrows.'),(157,'Ram, Portable',35,400,16,0,0,'Common','You can use a Portable Ram to break down doors. When doing so, you gain a +4 bonus to the Strength check. One other character can help you use the ram, giving you Advantage on this check.'),(158,'Rapier',2,2500,2,0,0,'Common','A rapier.'),(159,'Rations',2,50,16,0,0,'Common','Rations consist of travel-ready food, including jerky, dried fruit, hardtack, and nuts. See \"Malnutrition\" in \"Rules Glossary\" for the risks of not eating.'),(160,'Ring Mail',40,3000,1,0,0,'Common','A ring mail.'),(161,'Robe',4,100,16,0,0,'Common','A Robe has vocational or ceremonial significance. Some events and locations admit only people wearing a Robe bearing certain colors or symbols.'),(162,'Rope',5,100,16,0,0,'Common','As a Utilize action, you can tie a knot with Rope if you succeed on a DC 10 Dexterity (Sleight of Hand) check. The Rope can be burst with a successful DC 20 Strength (Athletics) check. You can bind an unwilling creature with the Rope only if the creature has the Grappled, Incapacitated, or Restrained condition. If the creature\'s legs are bound, the creature has the Restrained condition until it escapes. Escaping the Rope requires the creature to make a successful DC 15 Dexterity (Acrobatics) check as an action.'),(163,'Rowboat',100,5000,15,0,0,'Common','A small boat propelled by oars.'),(164,'Sack',0.5,1,16,0,0,'Common','A Sack holds up to 30 pounds within 1 cubic foot.'),(165,'Saddle (Exotic)',40,6000,16,0,0,'Common','A saddle designed for unusual mounts, such as aquatic or flying creatures.'),(166,'Saddle (Military)',30,2000,16,0,0,'Common','A saddle designed for combat, providing advantage on checks to remain mounted.'),(167,'Saddle (Riding)',25,1000,16,0,0,'Common','A standard saddle for riding mounts.'),(168,'Sailing Ship',0,1000000,15,0,0,'Common','A large ship propelled by sails.'),(169,'Scale Mail',45,5000,1,0,0,'Common','A scale mail.'),(170,'Scholar\'s Pack',22,4000,16,0,0,'Common','A Scholar\'s Pack contains the following items: Backpack, Book, Ink, Ink Pen, Lamp, 10 flasks of Oil, 10 sheets of Parchment, and Tinderbox.'),(171,'Scimitar',3,2500,2,0,0,'Common','A scimitar.'),(172,'Shield',6,1000,1,0,0,'Common','A shield.'),(173,'Shortbow',2,2500,2,0,0,'Common','A shortbow.'),(174,'Shortsword',2,1000,2,0,0,'Common','A shortsword.'),(175,'Shovel',5,200,16,0,0,'Common','Working for 1 hour, you can use a Shovel to dig a hole that is 5 feet on each side in soil or similar material.'),(176,'Sickle',2,100,2,0,0,'Common','A sickle.'),(177,'Signal Whistle',0,5,16,0,0,'Common','When blown as a Utilize action, a Signal Whistle produces a sound that can be heard up to 600 feet away.'),(178,'Sled',300,2000,15,0,0,'Common','A vehicle designed for travel over snow and ice.'),(179,'Sling',0,10,2,0,0,'Common','A sling.'),(180,'Smith\'s Tools (20 GP)',8,2000,5,0,0,'Common','Ability: Strength. Utilize: Pry open a door or container (DC 20). Craft: Any Melee weapon (except Club, Greatclub, Quarterstaff, and Whip), Medium armor (except Hide), Heavy armor, Ball Bearings, Bucket, Caltrops, Chain, Crowbar, Firearm Bullets, Grappling Hook, Iron Pot, Iron Spikes, Sling Bullets'),(181,'Spear',3,100,2,0,0,'Common','A spear.'),(182,'Spell Scroll',0,3000,16,0,0,'Common','A Spell Scroll (Cantrip) or Spell Scroll (Level 1) is a magic item that bears the words of a cantrip or level 1 spell, respectively, determined by the scroll\'s creator. If the spell is on your class\'s spell list, you can read the scroll and cast the spell using its normal casting time and without providing any Material components. If the spell requires a saving throw or an attack roll, the spell save DC is 13, and the attack bonus is +5. The scroll disintegrates when the casting is completed.'),(183,'Spikes, Iron',5,100,16,0,0,'Common','Iron Spikes come in bundles of ten. As a Utilize action, you can use a blunt object, such as a Light Hammer, to hammer a spike into wood, earth, or a similar material. You can do so to jam a door shut or to then tie a Rope or Chain to the Spike.'),(184,'Splint Armor',60,20000,1,0,0,'Common','A splint armor.'),(185,'Spyglass',1,100000,16,0,0,'Common','Objects viewed through a Spyglass are magnified to twice their size.'),(186,'String',0,10,16,0,0,'Common','String is 10 feet long. You can tie a knot in it as a Utilize action.'),(187,'Studded Leather Armor',13,4500,1,0,0,'Common','A studded leather armor.'),(188,'Tent',20,200,16,0,0,'Common','A Tent sleeps up to two Small or Medium creatures.'),(189,'Thieves\' Tools',1,2500,5,0,0,'Common','Ability: Dexterity. Utilize: Pick a lock (DC 15), or disarm a trap (DC 15)'),(190,'Tinderbox',1,50,16,0,0,'Common','A Tinderbox is a small container holding flint, fire steel, and tinder (usually dry cloth soaked in light oil) used to kindle a fire. Using it to light a Candle, Lamp, Lantern, or Torch—or anything else with exposed fuel—takes a Bonus Action. Lighting any other fire takes 1 minute.'),(191,'Tinker\'s Tools (50 GP)',10,5000,5,0,0,'Common','Ability: Dexterity. Utilize: Assemble a Tiny item composed of scrap, which falls apart in 1 minute (DC 20). Craft: Musket, Pistol, Bell, Bullseye Lantern, Flask, Hooded Lantern, Hunting Trap, Lock, Manacles, Mirror, Shovel, Signal Whistle, Tinderbox'),(192,'Torch',1,1,2,0,0,'Common','A Torch burns for 1 hour, casting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. When you take the Attack action, you can attack with the Torch, using it as a Simple Melee weapon. On a hit, the target takes 1 Fire damage.'),(193,'Trident',4,500,2,0,0,'Common','A trident.'),(194,'Vial',0,100,16,0,0,'Common','A Vial holds up to 4 ounces.'),(195,'Wagon',400,3500,15,0,0,'Common','A four-wheeled vehicle pulled by horses, designed for heavy cargo transport.'),(196,'War Pick',2,500,2,0,0,'Common','A war pick.'),(197,'Warhammer',5,1500,2,0,0,'Common','A warhammer.'),(198,'Warhorse',0,40000,15,0,0,'Common','A horse trained for combat and carrying heavy loads.'),(199,'Warship',0,2500000,15,0,0,'Common','A heavily armed ship designed for naval combat.'),(200,'Waterskin',5,20,16,0,0,'Common','A Waterskin holds up to 4 pints. If you don\'t drink sufficient water, you risk dehydration (see \"Rules Glossary\").'),(201,'Weaver\'s Tools (1 GP)',5,100,5,0,0,'Common','Ability: Dexterity. Utilize: Mend a tear in clothing (DC 10), or sew a Tiny design (DC 10). Craft: Padded Armor, Basket, Bedroll, Blanket, Fine Clothes, Net, Robe, Rope, Sack, String, Tent, Traveler\'s Clothes'),(202,'Whip',3,200,2,0,0,'Common','A whip.'),(203,'Woodcarver\'s Tools (1 GP)',5,100,5,0,0,'Common','Ability: Dexterity. Utilize: Carve a pattern in wood (DC 10). Craft: Club, Greatclub, Quarterstaff, Ranged weapons (except Pistol, Musket, and Sling), Arcane Focus, Arrows, Bolts, Druidic Focus, Ink Pen, Needles'),(204,'Adamantine Armor (Breastplate)',20,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(205,'Adamantine Armor (Chain Mail)',55,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(206,'Adamantine Armor (Chain Shirt)',20,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(207,'Adamantine Armor (Half Plate)',40,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(208,'Adamantine Armor (Plate)',65,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(209,'Adamantine Armor (Ring Mail)',40,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(210,'Adamantine Armor (Scale Mail)',45,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(211,'Adamantine Armor (Splint)',60,0,1,1,0,'Uncommon','This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you\'re wearing it, any Critical Hit against you becomes a normal hit.'),(212,'Ammunition of Aberration Slaying',0,0,2,1,0,'Very Rare','This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below. If a creature of that type takes damage from the ammunition, the creature makes a DC 17 Constitution saving throw, taking an extra 6d10 Force damage on a failed save or half as much extra damage on a successful one.\n\nAfter dealing its extra damage to a creature, the ammunition becomes nonmagical.\n\n| 1d100 | Creature Type |\n|-------|---------------|\n| 01–10 | Aberrations   |\n| 11–15 | Beasts        |\n| 16–20 | Celestials    |\n| 21–25 | Constructs    |\n| 26–35 | Dragons       |\n| 36–45 | Elementals    |\n| 46–50 | Humanoids     |\n| 51–60 | Fey           |\n| 61–70 | Fiends        |\n| 71–75 | Giants        |\n| 76–80 | Monstrosities |\n| 81–85 | Oozes         |\n| 86–90 | Plants        |\n| 91–00 | Undead        |'),(213,'Ammunition of Beast Slaying',0,0,2,1,0,'Very Rare','This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below. If a creature of that type takes damage from the ammunition, the creature makes a DC 17 Constitution saving throw, taking an extra 6d10 Force damage on a failed save or half as much extra damage on a successful one.\n\nAfter dealing its extra damage to a creature, the ammunition becomes nonmagical.\n\n| 1d100 | Creature Type |\n|-------|---------------|\n| 01–10 | Aberrations   |\n| 11–15 | Beasts        |\n| 16–20 | Celestials    |\n| 21–25 | Constructs    |\n| 26–35 | Dragons       |\n| 36–45 | Elementals    |\n| 46–50 | Humanoids     |\n| 51–60 | Fey           |\n| 61–70 | Fiends        |\n| 71–75 | Giants        |\n| 76–80 | Monstrosities |\n| 81–85 | Oozes         |\n| 86–90 | Plants        |\n| 91–00 | Undead        |'),(214,'Ammunition of Celestial Slaying',0,0,2,1,0,'Very Rare','This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below. If a creature of that type takes damage from the ammunition, the creature makes a DC 17 Constitution saving throw, taking an extra 6d10 Force damage on a failed save or half as much extra damage on a successful one.\n\nAfter dealing its extra damage to a creature, the ammunition becomes nonmagical.\n\n| 1d100 | Creature Type |\n|-------|---------------|\n| 01–10 | Aberrations   |\n| 11–15 | Beasts        |\n| 16–20 | Celestials    |\n| 21–25 | Constructs    |\n| 26–35 | Dragons       |\n| 36–45 | Elementals    |\n| 46–50 | Humanoids     |\n| 51–60 | Fey           |\n| 61–70 | Fiends        |\n| 71–75 | Giants        |\n| 76–80 | Monstrosities |\n| 81–85 | Oozes         |\n| 86–90 | Plants        |\n| 91–00 | Undead        |'),(215,'Ammunition of Construct Slaying',0,0,2,1,0,'Very Rare','This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below. If a creature of that type takes damage from the ammunition, the creature makes a D