CREATE TABLE `weapon_damage` (
  `weapon_id` int NOT NULL,
  `damage_roll` varchar(20) DEFAULT NULL,
  `damage_type_id` int NOT NULL,
  `always` tinyint(1) NOT NULL DEFAULT '1',
